"use client";

import { useEffect, useMemo, useRef, useState, type KeyboardEvent, type PointerEvent } from "react";
import { cn } from "@/lib/utils";
import type { BjorkTone } from "@/components/bjork-ui/_core/palette";
import { mulberry32 } from "@/components/bjork-ui/_core/random";
import { useChartCanvas, easeOut } from "@/components/bjork-ui/charts/_kit/canvas";
import { useChartTheme, chartFocusRing, ChartTable, ChartAnnouncer, type AnnouncerHandle } from "@/components/bjork-ui/charts/_kit/chrome";
import { clamp, crisp, damp, withAlpha, formatCompact, formatPercent, formatDateUTC, gaussian } from "@/components/bjork-ui/charts/_kit/scale";

export interface SparkPoint {
  t: number;
  v: number;
}

export interface SparkRow {
  id: string;
  label: string;
  sublabel?: string;
  data: SparkPoint[];
  format?: (v: number) => string;
  /** Which direction is good news. Tints the change chip. Default "up". */
  goodDirection?: "up" | "down";
}

export interface SparkTableProps {
  rows: SparkRow[];
  /** Header text when nothing is scrubbed, e.g. "Last 90 days". */
  periodLabel?: string;
  formatTime?: (t: number) => string;
  /** Posed shared index into every row's data. `null` shows the latest values. */
  index?: number | null;
  onIndexChange?: (index: number | null) => void;
  /** Selected row: drawn in the accent. */
  selectedId?: string | null;
  defaultSelectedId?: string | null;
  onSelectedChange?: (id: string | null) => void;
  rowHeight?: number;
  ariaLabel?: string;
  tone?: BjorkTone;
  attract?: boolean;
  className?: string;
}

const HEADER_H = 28;
const VALUE_TAU = 0.09;
const ENTER_MS = 900;
const ROW_ENTER_MS = 520;
const ATTRACT_IDLE_MS = 4000;
const ATTRACT_STEP_MS = 90;

const defaultFormat = (v: number) => formatCompact(v, 1);
// Input timestamps for the attract idle timer, read only from event handlers.
const clock = () => performance.now();
const defaultFormatTime = (t: number) => formatDateUTC(t);

function layoutColumns(w: number) {
  const narrow = w < 460;
  const gap = narrow ? 12 : 20;
  const label = narrow ? clamp(w * 0.28, 84, 120) : clamp(w * 0.24, 120, 200);
  const value = narrow ? 76 : 84;
  const delta = narrow ? 0 : 76;
  const spark = Math.max(40, w - label - value - delta - gap * (narrow ? 2 : 3));
  const sparkL = label + gap;
  const valueR = sparkL + spark + gap + value;
  return { narrow, gap, label, value, delta, spark, sparkL, sparkR: sparkL + spark, valueR, deltaR: w };
}

interface Run {
  enter: number;
  index: number | null;
  source: "pointer" | "keyboard" | "prop" | "attract" | null;
  disp: number[];
  ready: boolean;
  valueText: string[];
  deltaText: string[];
  lastInput: number;
  attractAt: number;
}

export function SparkTable({
  rows,
  periodLabel = "Latest",
  formatTime = defaultFormatTime,
  index,
  onIndexChange,
  selectedId: selectedProp,
  defaultSelectedId,
  onSelectedChange,
  rowHeight = 44,
  ariaLabel = "Metrics",
  tone: toneProp,
  attract = false,
  className,
}: SparkTableProps) {
  const { pal, reduce, vars } = useChartTheme(toneProp);
  const announcer = useRef<AnnouncerHandle>(null);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const timeRef = useRef<HTMLSpanElement>(null);
  const valueRefs = useRef<(HTMLSpanElement | null)[]>([]);
  const deltaRefs = useRef<(HTMLSpanElement | null)[]>([]);
  const arrowRefs = useRef<(HTMLSpanElement | null)[]>([]);
  const rectRef = useRef<DOMRect | null>(null);
  const [selState, setSelState] = useState<string | null>(defaultSelectedId === undefined ? (rows[0]?.id ?? null) : defaultSelectedId);
  const selected = selectedProp === undefined ? selState : selectedProp;

  const len = useMemo(() => rows.reduce((m, r) => Math.max(m, r.data.length), 0), [rows]);


  const cfg = useRef({ rows, selected, reduce, pal, attract, len, formatTime, periodLabel });
  useEffect(() => {
    cfg.current = { rows, selected, reduce, pal, attract, len, formatTime, periodLabel };
  });

  const st = useRef<Run>({
    enter: 0,
    index: index ?? null,
    source: index != null ? "prop" : null,
    disp: [],
    ready: false,
    valueText: [],
    deltaText: [],
    lastInput: 0,
    attractAt: 0,
  });

  const { rootRef, hostRef, canvasRef, size, wake } = useChartCanvas(({ ctx, w, dt }) => {
    const s = st.current;
    const c = cfg.current;
    const p = c.pal;
    const R = c.rows;
    const L = layoutColumns(w);
    const rh = rowHeight;

    if (c.attract && !c.reduce) {
      const now = performance.now();
      if ((!s.lastInput || now - s.lastInput > ATTRACT_IDLE_MS) && (s.source === null || s.source === "attract") && now - s.attractAt > ATTRACT_STEP_MS) {
        s.attractAt = now;
        s.index = s.index === null || s.index >= c.len - 1 ? Math.floor(c.len * 0.3) : s.index + 1;
        s.source = "attract";
      }
    }

    s.enter = c.reduce ? 1 : Math.min(1, s.enter + (dt * 1000) / ENTER_MS);
    const revealOf = (i: number) => {
      if (s.enter >= 1) return 1;
      const delay = (i / Math.max(1, R.length)) * (ENTER_MS - ROW_ENTER_MS);
      return easeOut(clamp((s.enter * ENTER_MS - delay) / ROW_ENTER_MS, 0, 1));
    };

    const idx = s.index;
    let moving = false;
    const xOf = (k: number, n: number) => L.sparkL + (k / Math.max(1, n - 1)) * (L.sparkR - L.sparkL);

    // Crosshair through every row at the shared index.
    if (idx !== null && c.len > 1) {
      const x = crisp(xOf(idx, c.len) - 0.5);
      ctx.strokeStyle = p.textFaint;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(x, HEADER_H);
      ctx.lineTo(x, HEADER_H + R.length * rh);
      ctx.stroke();
    }

    for (let i = 0; i < R.length; i++) {
      const row = R[i];
      const d = row.data;
      const n = d.length;
      if (!n) continue;
      const top = HEADER_H + i * rh;
      const pad = 9;
      let lo = Infinity;
      let hi = -Infinity;
      let iMin = 0;
      let iMax = 0;
      for (let k = 0; k < n; k++) {
        if (d[k].v < lo) {
          lo = d[k].v;
          iMin = k;
        }
        if (d[k].v > hi) {
          hi = d[k].v;
          iMax = k;
        }
      }
      if (hi - lo < 1e-9) {
        hi += 1;
        lo -= 1;
      }
      const yOf = (v: number) => top + pad + ((hi - v) / (hi - lo)) * (rh - pad * 2);
      const isSel = row.id === c.selected;
      const rev = revealOf(i);

      // Row divider.
      if (i > 0) {
        ctx.strokeStyle = p.hair;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(0, crisp(top));
        ctx.lineTo(w, crisp(top));
        ctx.stroke();
      }

      ctx.save();
      ctx.beginPath();
      ctx.rect(L.sparkL - 4, top, (L.sparkR - L.sparkL) * rev + 8, rh);
      ctx.clip();
      // Wash under the line.
      ctx.beginPath();
      for (let k = 0; k < n; k++) {
        const x = xOf(k, n);
        const y = yOf(d[k].v);
        if (k === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.lineTo(xOf(n - 1, n), top + rh - pad + 2);
      ctx.lineTo(xOf(0, n), top + rh - pad + 2);
      ctx.closePath();
      const grad = ctx.createLinearGradient(0, top + pad, 0, top + rh - pad);
      grad.addColorStop(0, withAlpha(isSel ? p.accent : p.text, isSel ? 0.16 : 0.06));
      grad.addColorStop(1, withAlpha(isSel ? p.accent : p.text, 0));
      ctx.fillStyle = grad;
      ctx.fill();
      ctx.beginPath();
      for (let k = 0; k < n; k++) {
        const x = xOf(k, n);
        const y = yOf(d[k].v);
        if (k === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.lineJoin = "round";
      ctx.lineCap = "round";
      ctx.lineWidth = isSel ? 1.75 : 1.25;
      ctx.strokeStyle = isSel ? p.accent : withAlpha(p.text, 0.62);
      ctx.stroke();
      ctx.restore();

      if (rev >= 1) {
        // Extremes as small hollow marks, the latest as a solid dot.
        for (const k of [iMin, iMax]) {
          ctx.beginPath();
          ctx.arc(xOf(k, n), yOf(d[k].v), 2, 0, Math.PI * 2);
          ctx.fillStyle = p.stage;
          ctx.fill();
          ctx.lineWidth = 1;
          ctx.strokeStyle = p.textSoft;
          ctx.stroke();
        }
        const k = idx !== null ? Math.min(n - 1, idx) : n - 1;
        ctx.beginPath();
        ctx.arc(xOf(k, n), yOf(d[k].v), 3, 0, Math.PI * 2);
        ctx.fillStyle = isSel ? p.accent : p.text;
        ctx.fill();
        ctx.lineWidth = 2;
        ctx.strokeStyle = p.stage;
        ctx.stroke();
      }

      // Value cell: counts toward the value at the index with a damped step.
      const k = idx !== null ? Math.min(n - 1, idx) : n - 1;
      const target = d[k].v;
      if (!s.ready || c.reduce || s.disp[i] === undefined) s.disp[i] = target;
      else {
        s.disp[i] = damp(s.disp[i], target, VALUE_TAU, dt);
        if (Math.abs(s.disp[i] - target) > Math.abs(target) * 1e-4 + 1e-9) moving = true;
        else s.disp[i] = target;
      }
      const fmt = row.format ?? defaultFormat;
      const vText = fmt(s.disp[i]);
      const vEl = valueRefs.current[i];
      if (vEl && s.valueText[i] !== vText) {
        s.valueText[i] = vText;
        vEl.textContent = vText;
      }
      // Change from the first point in the window to the index.
      const base = d[0].v;
      const chg = base ? (target - base) / Math.abs(base) : 0;
      const dText = `${chg >= 0 ? "+" : "−"}${formatPercent(Math.abs(chg), Math.abs(chg) < 0.1 ? 1 : 0)}`;
      const dEl = deltaRefs.current[i];
      if (dEl && s.deltaText[i] !== dText) {
        s.deltaText[i] = dText;
        dEl.textContent = dText;
        const good = (row.goodDirection ?? "up") === "up" ? chg >= 0 : chg <= 0;
        const chip = dEl.parentElement;
        if (chip) {
          chip.style.color = Math.abs(chg) < 0.0005 ? p.textMuted : good ? p.success : p.error;
          chip.style.background = withAlpha(Math.abs(chg) < 0.0005 ? p.text : good ? p.success : p.error, 0.1);
        }
        const ar = arrowRefs.current[i];
        if (ar) ar.textContent = chg >= 0 ? "↑" : "↓";
      }
    }
    s.ready = true;

    const tEl = timeRef.current;
    if (tEl) {
      const first = R.find((r) => r.data.length);
      const text = idx !== null && first ? c.formatTime(first.data[Math.min(first.data.length - 1, idx)].t) : c.periodLabel;
      if (tEl.textContent !== text) tEl.textContent = text;
      const x = idx !== null ? clamp(xOf(idx, c.len), L.sparkL + tEl.offsetWidth / 2, L.sparkR - tEl.offsetWidth / 2) : (L.sparkL + L.sparkR) / 2;
      tEl.style.transform = `translate3d(${x.toFixed(1)}px, 0, 0) translateX(-50%)`;
      tEl.dataset.active = idx !== null ? "true" : "false";
    }

    return moving || s.enter < 1 || (c.attract && !c.reduce);
  });

  useEffect(() => {
    wake();
  }, [rows, selected, pal, reduce, attract, wake]);

  useEffect(() => {
    if (index === undefined) return;
    st.current.index = index;
    st.current.source = index === null ? null : "prop";
    wake();
  }, [index, wake]);

  const describe = (i: number | null) => {
    const parts = rows.map((r) => {
      const d = r.data[i === null ? r.data.length - 1 : Math.min(r.data.length - 1, i)];
      return d ? `${r.label} ${(r.format ?? defaultFormat)(d.v)}` : r.label;
    });
    const first = rows.find((r) => r.data.length);
    const when = i !== null && first ? formatTime(first.data[Math.min(first.data.length - 1, i)].t) : periodLabel;
    return `${when}: ${parts.join(", ")}`;
  };

  const setIndex = (i: number | null, source: Run["source"]) => {
    const s = st.current;
    if (s.index === i && s.source === source) return;
    s.index = i;
    s.source = i === null ? null : source;
    onIndexChange?.(i);
    if (source === "keyboard") announcer.current?.say(describe(i));
    wake();
  };

  const select = (id: string | null) => {
    if (selectedProp === undefined) setSelState(id);
    onSelectedChange?.(id);
    const r = rows.find((x) => x.id === id);
    if (r) announcer.current?.say(`${r.label} selected`);
  };

  const onPointerMove = (e: PointerEvent<HTMLDivElement>) => {
    st.current.lastInput = clock();
    const rect = rectRef.current ?? wrapperRef.current?.getBoundingClientRect();
    if (!rect) return;
    const x = e.clientX - rect.left;
    const L = layoutColumns(rect.width);
    if (x < L.sparkL - 8 || x > L.sparkR + 8 || len < 2) {
      if (st.current.source === "pointer") setIndex(null, null);
      return;
    }
    setIndex(clamp(Math.round(((x - L.sparkL) / (L.sparkR - L.sparkL)) * (len - 1)), 0, len - 1), "pointer");
  };

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    const s = st.current;
    s.lastInput = clock();
    if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
      e.preventDefault();
      const step = (e.key === "ArrowLeft" ? -1 : 1) * (e.shiftKey ? 7 : 1);
      const cur = s.index === null || s.source === "attract" ? len - 1 : s.index;
      setIndex(clamp(s.index === null ? len - 1 : cur + step, 0, len - 1), "keyboard");
    } else if (e.key === "ArrowUp" || e.key === "ArrowDown") {
      e.preventDefault();
      const i = rows.findIndex((r) => r.id === selected);
      const next = rows[clamp((i < 0 ? 0 : i) + (e.key === "ArrowUp" ? -1 : 1), 0, rows.length - 1)];
      if (next) select(next.id);
    } else if (e.key === "Home") {
      e.preventDefault();
      setIndex(0, "keyboard");
    } else if (e.key === "End" || e.key === "Escape") {
      if (s.index === null) return;
      e.preventDefault();
      setIndex(null, null);
      announcer.current?.say(describe(null));
    }
  };

  const width = size.width;
  const cols = layoutColumns(width || 600);

  const tableRows = useMemo(
    () => rows.map((r) => [r.label, ...(r.data.length ? [(r.format ?? defaultFormat)(r.data[0].v), (r.format ?? defaultFormat)(r.data[r.data.length - 1].v)] : ["", ""])]),
    [rows],
  );
  const tableCols = useMemo(() => ["Metric", "Start of period", "Latest"], []);
  const height = HEADER_H + rows.length * rowHeight;

  return (
    <div ref={rootRef} data-loop="idle" className={cn("relative w-full select-none text-[color:var(--bjork-text)]", className)} style={{ ...vars, height }}>
      <div
        ref={wrapperRef}
        role="group"
        aria-roledescription="chart"
        aria-label={`${ariaLabel}. Left and right move through time for every row, up and down select a row, Escape returns to the latest values.`}
        tabIndex={0}
        onPointerEnter={() => {
          if (wrapperRef.current) rectRef.current = wrapperRef.current.getBoundingClientRect();
        }}
        onPointerMove={onPointerMove}
        onPointerDown={(e) => {
          if (wrapperRef.current) rectRef.current = wrapperRef.current.getBoundingClientRect();
          if (e.pointerType === "touch") onPointerMove(e);
        }}
        onPointerLeave={() => {
          if (st.current.source === "pointer") setIndex(null, null);
        }}
        onKeyDown={onKeyDown}
        className={cn("absolute inset-0 touch-pan-y rounded-[10px]", chartFocusRing)}
      >
        <div ref={hostRef} className="absolute inset-0">
          <canvas ref={canvasRef} role="img" aria-label={describe(null)} className="pointer-events-none absolute left-0 top-0" />
        </div>

        {/* Header */}
        <div aria-hidden="true" className="pointer-events-none absolute inset-x-0 top-0 font-mono text-[9px] uppercase leading-none tracking-[0.1em] text-[color:var(--bjork-text-soft)]" style={{ height: HEADER_H }}>
          <span className="absolute left-0 top-[9px] [text-box:trim-both_cap_alphabetic]">Metric</span>
          <span
            ref={timeRef}
            className="absolute left-0 top-[9px] whitespace-nowrap tabular-nums [text-box:trim-both_cap_alphabetic] data-[active=true]:text-[color:var(--bjork-text-medium)]"
          />
          <span className="absolute top-[9px] [text-box:trim-both_cap_alphabetic]" style={{ right: (width || 600) - cols.valueR }}>
            Value
          </span>
          {!cols.narrow && (
            <span className="absolute right-0 top-[9px] [text-box:trim-both_cap_alphabetic]">Change</span>
          )}
        </div>

        {rows.map((r, i) => {
          const isSel = r.id === selected;
          return (
            <div key={r.id} className="absolute inset-x-0" style={{ top: HEADER_H + i * rowHeight, height: rowHeight }}>
              <button
                type="button"
                tabIndex={-1}
                aria-pressed={isSel}
                onClick={() => select(isSel ? null : r.id)}
                className="absolute inset-y-0 left-0 flex flex-col items-start justify-center gap-[3px] text-left outline-none"
                style={{ width: cols.label }}
              >
                <span className="flex max-w-full items-center gap-1.5 truncate font-bjork-alpha text-[13px] font-medium leading-[16px] text-[color:var(--bjork-text)]">
                  <span
                    aria-hidden="true"
                    className="inline-block size-1.5 shrink-0 rounded-full transition-opacity duration-150 ease-out"
                    style={{ background: "var(--bjork-accent)", opacity: isSel ? 1 : 0 }}
                  />
                  <span className="truncate">{r.label}</span>
                </span>
                {r.sublabel && (
                  <span className="max-w-full truncate pl-3 font-mono text-[10px] leading-[14px] text-[color:var(--bjork-text-soft)]">
                    {r.sublabel}
                  </span>
                )}
              </button>
              <div
                aria-hidden="true"
                className="pointer-events-none absolute inset-y-0 flex flex-col items-end justify-center gap-[5px]"
                style={{ left: cols.valueR - cols.value, width: cols.value }}
              >
                <span
                  ref={(el) => {
                    valueRefs.current[i] = el;
                  }}
                  className="font-mono text-[14px] leading-none tabular-nums text-[color:var(--bjork-text)] [text-box:trim-both_cap_alphabetic]"
                />
                {cols.narrow && (
                  <span className="inline-flex items-center gap-0.5 rounded-[5px] px-1 py-[2px] font-mono text-[10px] leading-none tabular-nums">
                    <span
                      ref={(el) => {
                        arrowRefs.current[i] = el;
                      }}
                    />
                    <span
                      ref={(el) => {
                        deltaRefs.current[i] = el;
                      }}
                      className="[text-box:trim-both_cap_alphabetic]"
                    />
                  </span>
                )}
              </div>
              {!cols.narrow && (
                <div aria-hidden="true" className="pointer-events-none absolute inset-y-0 right-0 flex items-center justify-end" style={{ width: cols.delta }}>
                  <span className="inline-flex h-[20px] items-center gap-0.5 rounded-[6px] px-1.5 font-mono text-[11px] leading-none tabular-nums">
                    <span
                      ref={(el) => {
                        arrowRefs.current[i] = el;
                      }}
                      className="text-[10px]"
                    />
                    <span
                      ref={(el) => {
                        deltaRefs.current[i] = el;
                      }}
                      className="[text-box:trim-both_cap_alphabetic]"
                    />
                  </span>
                </div>
              )}
            </div>
          );
        })}
      </div>
      <ChartTable caption={ariaLabel} columns={tableCols} rows={tableRows} />
      <ChartAnnouncer ref={announcer} />
    </div>
  );
}

// Seeded daily metric for demos: trend, weekly seasonality and noise.
export function createMetricSeries(seed: number, days: number, opts: { base: number; trend?: number; weekly?: number; noise?: number; start?: number }): SparkPoint[] {
  const rnd = mulberry32(seed);
  const start = opts.start ?? Date.UTC(2025, 6, 1);
  const out: SparkPoint[] = [];
  let drift = 0;
  for (let i = 0; i < days; i++) {
    drift = drift * 0.85 + gaussian(rnd) * (opts.noise ?? 0.03);
    const weekly = Math.sin(((i % 7) / 7) * Math.PI * 2) * (opts.weekly ?? 0.04);
    out.push({ t: start + i * 86400000, v: opts.base * (1 + (opts.trend ?? 0) * (i / days) + weekly + drift) });
  }
  return out;
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export type BjorkTone = "dark" | "light";

// Canvas, WebGL and SVG attribute colours. DOM code uses the CSS tokens with these as fallbacks.
export const BJORK_PALETTE = {
  dark: {
    bg: "#050505", stage: "#111111", surface: "#121212", raised: "#161616", active: "#202020",
    border: "#232323", borderStrong: "#343434",
    text: "#ededed", textMedium: "rgba(237,237,237,0.72)", textMuted: "rgba(237,237,237,0.52)",
    textSoft: "rgba(237,237,237,0.36)", textFaint: "rgba(237,237,237,0.22)", hair: "rgba(237,237,237,0.12)",
    accent: "#ec5c13", accentInk: "#ec5c13", accentFill: "#b84a12", accentSoft: "rgba(236,92,19,0.12)", accentMuted: "rgba(236,92,19,0.24)",
    accentFg: "#fff2ea", success: "#4cc38a", warning: "#f2b544", error: "#ff5c4d",
  },
  light: {
    bg: "#f7f5ef", stage: "#f7f5ef", surface: "#fffcf6", raised: "#f5efe3", active: "#efe7d8",
    border: "#eee6db", borderStrong: "#e1d7c8",
    text: "#171717", textMedium: "rgba(23,23,23,0.72)", textMuted: "rgba(23,23,23,0.52)",
    textSoft: "rgba(23,23,23,0.36)", textFaint: "rgba(23,23,23,0.22)", hair: "rgba(23,23,23,0.10)",
    accent: "#ec7d43", accentInk: "#b4531f", accentFill: "#ec7d43", accentSoft: "rgba(236,125,67,0.10)", accentMuted: "rgba(236,125,67,0.20)",
    accentFg: "#3f2112", success: "#1f8a55", warning: "#a86b00", error: "#c8361f",
  },
} as const;

// Seeded randomness and noise. Deterministic for a given seed, so previews and tests repeat.

// Small fast PRNG. Returns floats in [0, 1).
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// FNV-1a 32-bit.
export function hashString(s: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

// Integer lattice hash to [-1, 1].
function latticeHash(seed: number, x: number, y = 0): number {
  let h = Math.imul(x | 0, 374761393) ^ Math.imul(y | 0, 668265263) ^ Math.imul(seed | 0, 2246822519);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return ((h >>> 0) / 4294967295) * 2 - 1;
}

function smooth(t: number): number {
  return t * t * (3 - 2 * t);
}

export function valueNoise1D(seed: number): (x: number) => number {
  return (x: number) => {
    const i = Math.floor(x);
    const f = x - i;
    const a = latticeHash(seed, i);
    const b = latticeHash(seed, i + 1);
    return a + (b - a) * smooth(f);
  };
}

export function fbm1D(seed: number, octaves = 3): (x: number) => number {
  const layers = Array.from({ length: octaves }, (_, o) => valueNoise1D(seed + o * 101));
  let norm = 0;
  for (let o = 0; o < octaves; o++) norm += 0.5 ** o;
  return (x: number) => {
    let sum = 0;
    let amp = 1;
    let freq = 1;
    for (let o = 0; o < octaves; o++) {
      sum += amp * layers[o](x * freq);
      amp *= 0.5;
      freq *= 2;
    }
    return sum / norm;
  };
}

export function valueNoise2D(seed: number): (x: number, y: number) => number {
  return (x: number, y: number) => {
    const xi = Math.floor(x);
    const yi = Math.floor(y);
    const fx = smooth(x - xi);
    const fy = smooth(y - yi);
    const a = latticeHash(seed, xi, yi);
    const b = latticeHash(seed, xi + 1, yi);
    const c = latticeHash(seed, xi, yi + 1);
    const d = latticeHash(seed, xi + 1, yi + 1);
    const top = a + (b - a) * fx;
    const bottom = c + (d - c) * fx;
    return top + (bottom - top) * fy;
  };
}

"use client";

// Canvas plumbing shared by the Charts collection. One hook gives a chart a measured host, a
// DPR-capped canvas that follows it, and a draw loop that pauses offscreen and idles when settled.

import { useCallback, useEffect, useRef, type RefObject } from "react";
import { useVisibleLoop } from "@/components/bjork-ui/_core/loop";
import { sizeCanvas, useElementSize } from "@/components/bjork-ui/_core/canvas";
import { cubicBezier, ease } from "@/components/bjork-ui/_core/motion";

export interface ChartFrame {
  ctx: CanvasRenderingContext2D;
  w: number;
  h: number;
  dt: number;
  t: number;
}

/**
 * `draw` runs inside `useVisibleLoop`. Return true to keep animating, false to go idle until `wake()`.
 * The loop root is `rootRef` (gets `data-loop`). The canvas is sized to `hostRef`.
 */
export function useChartCanvas(draw: (f: ChartFrame) => boolean) {
  const rootRef = useRef<HTMLDivElement>(null);
  const hostRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const size = useElementSize(hostRef);
  const sizeRef = useRef({ w: 0, h: 0, dpr: 1 });
  const drawRef = useRef(draw);
  useEffect(() => {
    drawRef.current = draw;
  });

  const frame = useCallback((dt: number, t: number) => {
    const canvas = canvasRef.current;
    const { w, h, dpr } = sizeRef.current;
    if (!canvas || !w || !h) return true;
    const ctx = canvas.getContext("2d");
    if (!ctx) return false;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);
    return drawRef.current({ ctx, w, h, dt, t });
  }, []);

  const { wake } = useVisibleLoop(rootRef as RefObject<HTMLElement | null>, frame);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !size.width || !size.height) return;
    sizeRef.current = { w: size.width, h: size.height, dpr: sizeCanvas(canvas, size.width, size.height) };
    wake();
  }, [size.width, size.height, wake]);

  return { rootRef, hostRef, canvasRef, size, wake };
}

// The house ease-out for entrances, usable in rAF code.
export const easeOut = cubicBezier(...(ease.out as unknown as [number, number, number, number]));
export const easeInOut = cubicBezier(...(ease.inOut as unknown as [number, number, number, number]));

// A 45 degree hatch pattern in `color`, for counterfactual and loss regions.
const hatchCache = new Map<string, CanvasPattern | null>();
export function hatchPattern(ctx: CanvasRenderingContext2D, color: string, gap = 5, width = 1): CanvasPattern | null {
  const key = `${color}|${gap}|${width}`;
  if (hatchCache.has(key)) return hatchCache.get(key)!;
  if (typeof document === "undefined") return null;
  const tile = document.createElement("canvas");
  const s = gap * 2;
  tile.width = s * 2;
  tile.height = s * 2;
  const c = tile.getContext("2d");
  if (!c) return null;
  c.scale(2, 2);
  c.strokeStyle = color;
  c.lineWidth = width;
  c.beginPath();
  for (let k = -s; k <= s * 2; k += gap) {
    c.moveTo(k, s);
    c.lineTo(k + s, 0);
  }
  c.stroke();
  const pattern = ctx.createPattern(tile, "repeat");
  pattern?.setTransform(new DOMMatrix().scale(0.5, 0.5));
  hatchCache.set(key, pattern);
  return pattern;
}

// Rounded rect path with independent top and bottom radii (bars: round data end, square baseline).
export function roundRectPath(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  rTop: number,
  rBottom = 0,
) {
  if (w <= 0 || h <= 0) return;
  const rt = Math.min(rTop, w / 2, h / 2);
  const rb = Math.min(rBottom, w / 2, h / 2);
  ctx.moveTo(x + rt, y);
  ctx.lineTo(x + w - rt, y);
  if (rt) ctx.arcTo(x + w, y, x + w, y + rt, rt);
  ctx.lineTo(x + w, y + h - rb);
  if (rb) ctx.arcTo(x + w, y + h, x + w - rb, y + h, rb);
  ctx.lineTo(x + rb, y + h);
  if (rb) ctx.arcTo(x, y + h, x, y + h - rb, rb);
  ctx.lineTo(x, y + rt);
  if (rt) ctx.arcTo(x, y, x + rt, y, rt);
  ctx.closePath();
}

export interface PlacedLabel {
  text: string;
  x: number;
  y: number;
  /** translate percentages applied after the position, e.g. -50 to centre. */
  ax?: number;
  ay?: number;
  opacity?: number;
}

// Writes a pool of absolutely positioned label spans from the loop: text only when it changes,
// position by transform only. Unused spans hide.
export function writeLabels(els: (HTMLElement | null)[], cache: string[], items: PlacedLabel[]) {
  for (let i = 0; i < els.length; i++) {
    const el = els[i];
    if (!el) continue;
    const it = items[i];
    if (!it) {
      if (el.style.opacity !== "0") el.style.opacity = "0";
      continue;
    }
    if (cache[i] !== it.text) {
      cache[i] = it.text;
      el.textContent = it.text;
    }
    el.style.opacity = String(it.opacity ?? 1);
    el.style.transform = `translate3d(${it.x.toFixed(2)}px, ${it.y.toFixed(2)}px, 0) translate(${it.ax ?? 0}%, ${it.ay ?? -50}%)`;
  }
}

"use client";

import { useCallback, useEffect, useMemo, useRef, type RefObject } from "react";

export interface VisibleLoopOptions {
  enabled?: boolean;
  fpsCap?: number;
  rootMargin?: string;
}

/**
 * Runs `frame(dt, t)` on requestAnimationFrame while the element is near the viewport,
 * the tab is visible and `enabled` is not false. Return `false` from `frame` to go idle
 * until `wake()` is called. Writes `data-loop` on the element: running, idle or paused.
 */
export function useVisibleLoop(
  ref: RefObject<HTMLElement | null>,
  frame: (dt: number, t: number) => boolean | void,
  opts?: VisibleLoopOptions,
): { wake: () => void } {
  const enabled = opts?.enabled !== false;
  const fpsCap = opts?.fpsCap ?? 0;
  const rootMargin = opts?.rootMargin ?? "96px";

  const frameRef = useRef(frame);
  useEffect(() => {
    frameRef.current = frame;
  }, [frame]);

  const wakeRef = useRef<() => void>(() => {});
  const wake = useCallback(() => wakeRef.current(), []);

  useEffect(() => {
    const el = ref.current;
    if (!el || typeof window === "undefined") return;

    let wants = true; // false once the frame callback returns false
    let inView = false;
    let raf = 0;
    let last = 0;
    let t = 0;
    const minFrame = fpsCap > 0 ? 1000 / fpsCap : 0;

    const canRun = () => enabled && inView && document.visibilityState === "visible";
    const stop = () => {
      if (raf) cancelAnimationFrame(raf);
      raf = 0;
    };

    const update = () => {
      if (!enabled) {
        stop();
        el.dataset.loop = "paused";
        return;
      }
      if (!wants) {
        stop();
        el.dataset.loop = "idle";
        return;
      }
      if (!canRun()) {
        stop();
        el.dataset.loop = "paused";
        return;
      }
      el.dataset.loop = "running";
      if (!raf) {
        last = performance.now();
        raf = requestAnimationFrame(tick);
      }
    };

    const tick = (now: number) => {
      raf = 0;
      if (!canRun() || !wants) {
        update();
        return;
      }
      const elapsed = now - last;
      if (minFrame && elapsed < minFrame - 0.5) {
        raf = requestAnimationFrame(tick);
        return;
      }
      last = now;
      const dt = Math.min(0.05, Math.max(0, elapsed / 1000));
      t += dt;
      const keep = frameRef.current(dt, t);
      if (keep === false) {
        wants = false;
        update();
        return;
      }
      raf = requestAnimationFrame(tick);
    };

    const observer = new IntersectionObserver(
      ([entry]) => {
        inView = entry.isIntersecting;
        update();
      },
      { rootMargin },
    );
    observer.observe(el);

    const onVisibility = () => update();
    document.addEventListener("visibilitychange", onVisibility);

    wakeRef.current = () => {
      wants = true;
      update();
    };

    update();

    return () => {
      stop();
      observer.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
      wakeRef.current = () => {};
    };
  }, [ref, enabled, fpsCap, rootMargin]);

  return useMemo(() => ({ wake }), [wake]);
}

// matchMedia based check. False on the server.
export function isCoarsePointer(): boolean {
  if (typeof window === "undefined" || typeof window.matchMedia !== "function") return false;
  return window.matchMedia("(pointer: coarse)").matches;
}

"use client";

import { useEffect, useState, type RefObject } from "react";
import { isCoarsePointer } from "./loop";

// Caps DPR at 1.5 on coarse pointers and 2 otherwise.
export function defaultMaxDpr(): number {
  return isCoarsePointer() ? 1.5 : 2;
}

// Sets the backing size for a CSS box and returns the DPR used.
export function sizeCanvas(
  canvas: HTMLCanvasElement,
  cssW: number,
  cssH: number,
  maxDpr: number = defaultMaxDpr(),
): number {
  const dpr = Math.min(typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1, maxDpr);
  canvas.width = Math.max(1, Math.round(cssW * dpr));
  canvas.height = Math.max(1, Math.round(cssH * dpr));
  canvas.style.width = `${cssW}px`;
  canvas.style.height = `${cssH}px`;
  return dpr;
}

// Rounded size of an element, kept current with a ResizeObserver.
export function useElementSize(ref: RefObject<HTMLElement | null>): { width: number; height: number } {
  const [size, setSize] = useState({ width: 0, height: 0 });

  useEffect(() => {
    const el = ref.current;
    if (!el || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver((entries) => {
      const box = entries[0]?.contentRect;
      if (!box) return;
      const width = Math.round(box.width);
      const height = Math.round(box.height);
      setSize((prev) => (prev.width === width && prev.height === height ? prev : { width, height }));
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, [ref]);

  return size;
}

