      )}
      style={style}
    >
      {title !== undefined && (
        <div className="mb-1.5 whitespace-nowrap font-mono text-[10px] uppercase leading-none tracking-[0.08em] text-[color:var(--bjork-text-soft)] [text-box:trim-both_cap_alphabetic]">
          {title}
